'use client'
import {
  composeRefs,
  createMachine,
  focusElement,
  useEffectPropSignal,
  useMachine,
  useSignal,
  useSignalEffect,
  useSignals,
} from '@cascivo/core'
import { cloneElement, useRef } from 'react'
import type { KeyboardEvent, MouseEvent, ReactElement, ReactNode, Ref } from 'react'
import styles from './dropdown.module.css'

const machine = createMachine({
  initial: 'closed' as const,
  states: {
    closed: { on: { OPEN: 'open' } },
    open: { on: { CLOSE: 'closed' } },
  },
})

/** A selectable row in a `Dropdown` menu. */
export interface DropdownMenuItem {
  label: string
  value: string
  icon?: ReactNode
  disabled?: boolean
}

/**
 * A horizontal rule between groups of items. Carries no data, takes no `label`/`value`, and
 * is skipped by keyboard navigation and selection.
 */
export interface DropdownSeparatorItem {
  kind: 'separator'
}

/**
 * A `Dropdown` entry: either a selectable item or a separator.
 *
 * The union is tagged on `kind` (the catalog convention — `type` is reserved for HTML-ish
 * meanings), so a separator cannot carry data that would be silently discarded.
 */
export type DropdownItem = DropdownMenuItem | DropdownSeparatorItem

/**
 * Narrows to the selectable rows. One predicate for every call site — nav, selection and
 * render — so the three cannot disagree about what counts as a separator.
 */
function isMenuItem(item: DropdownItem): item is DropdownMenuItem {
  return !('kind' in item)
}

export interface DropdownProps {
  trigger: ReactElement
  items: DropdownItem[]
  onSelect?: (value: string) => void
  /**
   * Which trigger edge the menu aligns to. `bottom-start` hangs it from the trigger's start
   * edge, `bottom-end` from its end edge — use `bottom-end` for a trigger near the end of
   * the viewport.
   *
   * @defaultValue `bottom-start`
   * @see the component manifest
   */
  placement?: 'bottom-start' | 'bottom-end'
  open?: boolean
  onOpenChange?: (open: boolean) => void
}

export function Dropdown({
  trigger,
  items,
  onSelect,
  placement = 'bottom-start',
  open,
  onOpenChange,
}: DropdownProps) {
  useSignals()
  const [state, send] = useMachine(machine)
  const rootRef = useRef<HTMLDivElement>(null)
  const triggerRef = useRef<HTMLElement>(null)
  const menuRef = useRef<HTMLDivElement>(null)
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([])
  const activeIndex = useSignal(-1)

  const isControlled = open !== undefined
  const isOpen = isControlled ? open : state.value === 'open'
  const openSignal = useEffectPropSignal(isOpen)

  const enabledIndexes = items
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => isMenuItem(item) && !item.disabled)
    .map(({ index }) => index)

  const setOpen = (next: boolean) => {
    if (!isControlled) send(next ? 'OPEN' : 'CLOSE')
    onOpenChange?.(next)
  }

  // Move keyboard focus to the active item whenever it changes while open.
  useSignalEffect(() => {
    const index = activeIndex.value
    if (openSignal.value && index >= 0) {
      itemRefs.current[index]?.focus()
    }
  })

  // Reset / seed the active item as the menu opens and closes.
  useSignalEffect(() => {
    if (openSignal.value) {
      activeIndex.value = enabledIndexes[0] ?? -1
    } else {
      activeIndex.value = -1
    }
  })

  // Open/close the popover and sync light-dismiss (toggle event) back to state.
  useSignalEffect(() => {
    if (openSignal.value) {
      menuRef.current?.showPopover()
    } else {
      menuRef.current?.hidePopover()
    }
  })

  useSignalEffect(() => {
    const menu = menuRef.current
    if (!menu) return
    const handleToggle = (event: Event) => {
      const toggle = event as ToggleEvent
      if (toggle.newState === 'closed') setOpen(false)
    }
    menu.addEventListener('toggle', handleToggle)
    return () => menu.removeEventListener('toggle', handleToggle)
  })

  const selectAt = (index: number) => {
    const item = items[index]
    if (!item || !isMenuItem(item) || item.disabled) return
    onSelect?.(item.value)
    setOpen(false)
    focusElement(triggerRef.current)
  }

  const moveActive = (delta: number) => {
    if (enabledIndexes.length === 0) return
    const current = enabledIndexes.indexOf(activeIndex.value)
    const next = (current + delta + enabledIndexes.length) % enabledIndexes.length
    activeIndex.value = enabledIndexes[next] ?? -1
  }

  const handleMenuKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault()
        moveActive(1)
        break
      case 'ArrowUp':
        event.preventDefault()
        moveActive(-1)
        break
      case 'Home':
        event.preventDefault()
        activeIndex.value = enabledIndexes[0] ?? -1
        break
      case 'End':
        event.preventDefault()
        activeIndex.value = enabledIndexes[enabledIndexes.length - 1] ?? -1
        break
      case 'Escape':
        event.preventDefault()
        setOpen(false)
        focusElement(triggerRef.current)
        break
      case 'Enter':
      case ' ':
        event.preventDefault()
        selectAt(activeIndex.value)
        break
    }
  }

  const triggerEl = trigger as ReactElement<{
    ref?: Ref<HTMLElement>
    onClick?: (e: MouseEvent) => void
  }>
  const renderedTrigger = cloneElement(triggerEl, {
    ref: composeRefs(triggerRef, triggerEl.props.ref),
    onClick: (event: MouseEvent) => {
      triggerEl.props.onClick?.(event)
      setOpen(!isOpen)
    },
    'aria-haspopup': 'menu',
    'aria-expanded': isOpen,
  } as Record<string, unknown>)

  return (
    <div ref={rootRef} className={styles['root']}>
      {renderedTrigger}
      <div
        ref={menuRef}
        popover="auto"
        role="menu"
        data-placement={placement}
        data-state={isOpen ? 'open' : 'closed'}
        className={styles['menu']}
        onKeyDown={handleMenuKeyDown}
      >
        {items.map((item, index) =>
          !isMenuItem(item) ? (
            <div key={`sep-${index}`} role="separator" className={styles['separator']} />
          ) : (
            <button
              key={item.value}
              type="button"
              role="menuitem"
              ref={(el) => {
                itemRefs.current[index] = el
              }}
              tabIndex={activeIndex.value === index ? 0 : -1}
              disabled={item.disabled}
              className={styles['item']}
              onClick={() => selectAt(index)}
            >
              {item.icon && (
                <span className={styles['icon']} aria-hidden="true">
                  {item.icon}
                </span>
              )}
              {item.label}
            </button>
          ),
        )}
      </div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    display: inline-flex;
  }

  .menu {
    position: absolute;
    inset-block-start: calc(100% + var(--cascivo-space-1));
    z-index: var(--cascivo-z-dropdown);
    min-inline-size: 10rem;
    max-inline-size: calc(100vw - var(--cascivo-space-4, 1rem));
    padding: var(--cascivo-space-1);
    background-color: var(--cascivo-color-surface-overlay);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-overlay);
    box-shadow: var(--cascivo-shadow-overlay);
    opacity: 0;
    visibility: hidden;
    translate: 0 -0.25rem;
    transition:
      opacity var(--cascivo-motion-enter),
      translate var(--cascivo-motion-enter),
      visibility var(--cascivo-motion-enter);

    &[data-placement='bottom-start'] {
      inset-inline-start: 0;
    }
    &[data-placement='bottom-end'] {
      inset-inline-end: 0;
    }

    &[data-state='open'] {
      opacity: 1;
      visibility: visible;
      translate: 0 0;
    }

    @starting-style {
      &[data-state='open'] {
        opacity: 0;
        translate: 0 -0.25rem;
      }
    }
  }

  @supports (anchor-name: --a) and (position-anchor: --a) {
    .menu {
      position: fixed;
      inset: auto;
      position-anchor: var(--cascivo-dropdown-anchor, --dropdown-trigger);
      /* A menu under a wide trigger used to sit at its own content width, so a full-width
         select-style button opened a narrow panel hanging off one edge. `anchor-size` reads
         the trigger; `max()` keeps the 10rem floor for an icon-sized one. The static
         `min-inline-size: 10rem` on `.menu` above is the fallback. */
      min-inline-size: max(10rem, anchor-size(self-inline));
    }

    .menu[data-placement='bottom-start'] {
      position-area: block-end span-inline-start;
      inset-inline-start: 0;
    }

    .menu[data-placement='bottom-end'] {
      position-area: block-end span-inline-end;
      inset-inline-end: 0;
    }

    @media (prefers-reduced-motion: no-preference) {
      .menu {
        transition:
          opacity var(--cascivo-motion-enter),
          translate var(--cascivo-motion-enter),
          visibility var(--cascivo-motion-enter),
          display var(--cascivo-motion-enter) allow-discrete,
          overlay var(--cascivo-motion-enter) allow-discrete;
      }

      @starting-style {
        .menu[data-state='open'] {
          opacity: 0;
          translate: 0 -0.25rem;
        }
      }
    }
  }

  .item {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    inline-size: 100%;
    padding-inline: var(--cascivo-space-3);
    padding-block: var(--cascivo-space-2);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    text-align: start;
    color: var(--cascivo-color-text);
    background: transparent;
    border: none;
    border-radius: var(--cascivo-radius-item);
    cursor: pointer;

    &:hover:not(:disabled),
    &:focus-visible {
      outline: none;
      background-color: var(--cascivo-color-bg-subtle);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  }

  .icon {
    display: inline-flex;
    align-items: center;
    color: var(--cascivo-color-text-muted);
  }

  .separator {
    block-size: 1px;
    margin-block: var(--cascivo-space-1);
    background-color: var(--cascivo-color-border);
  }
}

@media (forced-colors: active) {
  .menu {
    border: 1px solid ButtonText;
  }

  .item:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Dropdown',
  description: 'Menu of actions revealed from a trigger',
  category: 'overlay',
  clientJs: 'required',
  states: ['closed', 'open'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'trigger',
      description: 'The element that opens the dropdown when activated.',
      type: 'ReactElement',
      required: true,
    },
    {
      name: 'items',
      description:
        "Menu entries. A selectable row is `{ label, value, icon?, disabled? }`; a rule between groups is `{ kind: 'separator' }`, which takes no label or value. The union is tagged on `kind`, so a separator cannot carry data that would be silently discarded.",
      type: "({ label: string; value: string; icon?: ReactNode; disabled?: boolean } | { kind: 'separator' })[]",
      required: true,
    },
    {
      name: 'onSelect',
      description: 'Called with the selected value.',
      type: '(value: string) => void',
      required: false,
    },
    {
      name: 'placement',
      description:
        "Which trigger edge the menu aligns to. `bottom-start` hangs it from the trigger's start edge, `bottom-end` from its end edge — use `bottom-end` for a trigger near the end of the viewport.",
      type: "'bottom-start' | 'bottom-end'",
      required: false,
      default: 'bottom-start',
    },
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'onOpenChange',
      description: 'Called with the next open state when it changes.',
      type: '(open: boolean) => void',
      required: false,
    },
  ],
  typeDefs: [
    {
      name: 'DropdownMenuItem',
      description: 'A selectable row in the menu.',
      fields: [
        { name: 'label', type: 'string', required: true, description: 'Visible item text.' },
        { name: 'value', type: 'string', required: true, description: 'Passed to `onSelect`.' },
        { name: 'icon', type: 'ReactNode', required: false, description: 'Leading icon.' },
        {
          name: 'disabled',
          type: 'boolean',
          required: false,
          description: 'Skips the item in keyboard navigation and selection.',
        },
      ],
    },
    {
      name: 'DropdownSeparatorItem',
      description: 'A rule between groups. Carries no data and is skipped by keyboard navigation.',
      fields: [{ name: 'kind', type: "'separator'", required: true, description: 'Discriminant.' }],
    },
  ],
  tokens: [
    '--cascivo-color-surface-overlay',
    '--cascivo-color-border',
    '--cascivo-color-bg-subtle',
    '--cascivo-radius-md',
    '--cascivo-z-dropdown',
  ],
  accessibility: {
    role: 'menu',
    wcag: '2.2-AA',
    keyboard: ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', 'Space', 'Escape'],
    apgPattern: 'menu',
    reducedMotion: true,
    forcedColors: true,
  },
  examples: [
    {
      title: 'Basic',
      code: '<Dropdown trigger={<Button>Actions</Button>} items={[{ label: "Edit", value: "edit" }]} onSelect={handle} />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['overlay', 'menu', 'actions'],
  intent: {
    whenToUse: [
      'Revealing a short menu of actions from a trigger button (row actions, "More" overflow, account menu)',
      'Grouping related commands behind one affordance with optional icons and separators',
    ],
    whenNotToUse: [
      'Selecting a persistent value for a form — use Select or Combobox',
      'A global searchable command palette — use CommandMenu; right-click context actions — use ContextMenu',
    ],
    antiPatterns: [
      {
        bad: 'Using Dropdown to choose a form value and reading the selection as field state',
        good: 'Use Select/Combobox which expose role="combobox" and a controlled value',
        why: 'Dropdown items are role="menuitem" actions fired via onSelect — there is no selected-value semantics for assistive tech or forms',
      },
    ],
    related: [
      {
        name: 'Select',
        relationship: 'alternative',
        reason: 'Use for choosing and persisting a single form value',
      },
      {
        name: 'CommandMenu',
        relationship: 'alternative',
        reason: 'Use for a searchable global action palette',
      },
      {
        name: 'Button',
        relationship: 'pairs-with',
        reason: 'The trigger is typically a Button passed via the trigger prop',
      },
    ],
    a11yRationale:
      'The menu is role="menu" with role="menuitem" buttons and roving tabindex; the trigger gets aria-haspopup="menu" and aria-expanded via cloneElement; arrow/Home/End/Enter/Escape are handled and focus returns to the trigger on select or close, and popover="auto" provides light-dismiss synced back to state via the toggle event',
    flexibility: [
      {
        area: 'trigger element',
        level: 'flexible',
        note: 'Any ReactElement works as the trigger; ref and aria props are merged in',
      },
      {
        area: 'controlled vs uncontrolled',
        level: 'flexible',
        note: 'Supports open + onOpenChange or fully internal state',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Menu styling resolves to semantic --cascivo-color-* / --cascivo-z-dropdown tokens',
      },
    ],
  },
}
